 if(kind!=='unit-covariant-predictions')throw new Error('Unknown physical-modeling lab.');const r=unitCovariance(values),ys=r.curves.flatMap(c=>c.map(p=>p[1])),lo=Math.min(0,...ys),hi=Math.max(0,...ys),pad=Math.max(1,(hi-lo)*.05);return{plot:'continuous',units:r,statement:'One-dimensional constant acceleration with x0=0 and SI reference inputs. Positive base-unit rescalings use new length unit10^l meters, mass unit10^m kilograms and time unit10^s seconds. Transform every coefficient, evaluate at the same physical time, and convert positions back to meters. Blue physical and orange coherent curves coincide exactly on the supported rational grid. Green deliberately keeps velocity/acceleration numbers unchanged in the new units and generally describes a different system; an accidental match at a query does not prove curve equality. Mass affects force and energy but not the prescribed trajectory. This coordinate consistency does not validate constant acceleration as a model of reality. No affine temperature conversion or measurement uncertainty is modeled.',stats:{'query physical time seconds':r.t,'new length unit in meters':r.lengthUnit.value,'new mass unit in kilograms':r.massUnit.value,'new time unit in seconds':r.timeUnit.value,'mass in new units':r.massPrime.value,'initial velocity in new units':r.initialVelocityPrime.value,'acceleration in new units':r.accelerationPrime.value,'same query time in new units':r.timePrime.value,'physical query position meters':r.position.value,'query position in new units':r.positionPrime.value,'physical force newtons':r.force.value,'force in new units':r.forcePrime.value,'physical kinetic energy joules':r.energy.value,'energy in new units':r.energyPrime.value,'unchanged-number query position meters':r.wrongPosition.value,'1{exact position reconstruction}':Number(r.exactPosition),'1{exact velocity reconstruction}':Number(r.exactVelocity),'1{exact force reconstruction}':Number(r.exactForce),'1{exact energy reconstruction}':Number(r.exactEnergy),'1{unchanged-number match at query only}':Number(r.unchangedNumbersMatchAtQuery)},curves:r.curves,curveColors:['blue','orange','green'],dots:[[r.t,r.position.value]],dotColors:['blue'],bounds:[0,5,lo-pad,hi+pad],table:{headers:['quantity','SI numerical value','new-unit exact numerical value','new-unit numerical approximation'],rows:[['mass',r.m,r.massPrime.label,r.massPrime.value],['query time',r.t,r.timePrime.label,r.timePrime.value],['position',r.position.value,r.positionPrime.label,r.positionPrime.value],['velocity',r.finalVelocity.value,r.finalVelocityPrime.label,r.finalVelocityPrime.value],['force',r.force.value,r.forcePrime.label,r.forcePrime.value],['kinetic energy',r.energy.value,r.energyPrime.label,r.energyPrime.value]]}};
